/**
 * Sample data for demos / FE integration. Goes through the same validation as the API (createRecord), so every
 * rule, auto status, Queue item and auto income entry is produced exactly as for real data.
 *
 *   npm run seed:sample              refuses if the database already has entities
 *   npm run seed:sample -- --reset   wipes the database first, but ONLY if every record in it is sample data or auto-generated
 *
 * Every sample record carries createdByName = "seed-demo".
 */
const mongoose = require('mongoose');
const config = require('../src/config');
const registry = require('../src/resources');
const { createRecord, updateRecord } = require('../src/core/record');
const { getEnv } = require('../src/core/env');
const { Counter } = require('../src/models/system');
const D = require('../src/lib/dates');

const TAG = 'seed-demo';
const usd = (dollars) => ({ amountMinor: Math.round(dollars * 100), currency: 'USD' });

async function reset() {
  const foreign = [];
  for (const cfg of registry.all()) {
    const n = await cfg.Model.countDocuments({ createdByName: { $ne: TAG }, autoGenerated: { $ne: true }, source: { $nin: ['auto'] }, isCounterpart: { $ne: true } });
    if (n) foreign.push(`${cfg.path}: ${n}`);
  }
  if (foreign.length) throw new Error(`Database has records that are not sample data, refusing to wipe:\n  ${foreign.join('\n  ')}`);
  for (const cfg of registry.all()) await cfg.Model.deleteMany({});
  await Counter.deleteMany({});
  console.log('database wiped');
}

