async function main() {
  await mongoose.connect(config.mongoUri);
  console.log(`database: ${mongoose.connection.db.databaseName}`);
  for (const name of mongoose.modelNames()) await mongoose.model(name).syncIndexes();
  if (process.argv.includes('--reset')) await reset();
  else if (await registry.get('entities').Model.exists({})) throw new Error('Database already has data. Use --reset to replace sample data.');
  const counts = await run();
  const total = Object.values(counts).reduce((a, b) => a + b, 0);
  for (const [k, v] of Object.entries(counts)) console.log(`  ${k.padEnd(24)} ${v}`);
  console.log(`done: ${total} records`);
  await require('../src/services/queue').syncAll?.({ env: await getEnv() }).catch(() => {});
  await mongoose.disconnect();
}

if (require.main === module) {
  main().catch((e) => {
    console.error(e.message);
    process.exit(1);
  });
}

module.exports = { run, reset };
